class Solution {
    private fun palindrome(s:String,mask:Int):Boolean{
        val indices=s.indices.filter{
            mask and (1 shl it)!=0
        };
        var left=0;
        var right=indices.lastIndex;
        while(left<right)if(s[indices[left++]]!=s[indices[right--]])return false;
        return true
    };
    fun maxProduct(s:String):Int{
        val total=1 shl s.length;
        val length=IntArray(total);
        for(mask in 1 until total)if(palindrome(s,mask))length[mask]=Integer.bitCount(mask);
        var answer=0;
        for(first in 1 until total)for(second in first+1 until total)if(first and second==0)answer=maxOf(answer,length[first]*length[second]);
        return answer
    }
}

